class CategoryListComponent {
    constructor(tableSvc, categoryService, router, commonService) {
        this.tableSvc = tableSvc;
        this.categoryService = categoryService;
        this.router = router;
        this.commonService = commonService;
        this.displayData = [];
        this.dataList = [];
        this.apiUrl = src_environments_environment__WEBPACK_IMPORTED_MODULE_0__.environment.baseUrl;
        // Pagination variables
        this.pageIndex = 1;
        this.pageSize = 10;
        this.orderColumn = [
            {
                title: 'SI.No.',
            },
            {
                title: 'Category Name',
            },
            {
                title: 'Package',
            },
            {
                title: 'Type',
            },
            {
                title: 'Status',
            },
            {
                title: 'Actions',
            }
        ];
    }
    ngOnInit() {
        this.fetchData();
    }
    fetchData() {
        this.categoryService.getCategories(this.pageIndex, this.pageSize).subscribe({
            next: (res) => {
                this.displayData = res.result.data;
                this.dataList = res.result.data;
                this.total = res.result.totalCount;
            },
            error: (err) => {
                console.error('Error fetching category:', err);
            }
        });
    }
    deleteItem(endpoint, id) {
        if (confirm('Are you sure you want to delete this item?')) {
            this.commonService.deleteItem(endpoint, id).subscribe({
                next: () => {
                    alert('Item deleted successfully');
                    this.fetchData();
                },
                error: (err) => {
                    console.error('Error deleting item:', err);
                    const errorMessage = err?.error?.message || 'Failed to delete the item';
                    alert(errorMessage);
                },
            });
        }
    }
    onPageChange(pageIndex) {
        this.pageIndex = pageIndex;
        this.fetchData();
    }
}
