class PackageListComponent {
    constructor(tableSvc, packageService, commonService) {
        this.tableSvc = tableSvc;
        this.packageService = packageService;
        this.commonService = commonService;
        this.displayData = [];
        this.dataList = [];
        this.orderColumn = [
            {
                title: 'SI.No.',
            },
            {
                title: 'Package Name',
            },
            {
                title: 'Age',
            },
            {
                title: 'Description',
            },
            {
                title: 'Status',
            },
            {
                title: 'Actions',
            }
        ];
    }
    ngOnInit() {
        this.fetchPackages();
    }
    fetchPackages() {
        this.packageService.getPackages().subscribe({
            next: (res) => {
                this.displayData = res.result;
                this.dataList = res.result;
            },
            error: (err) => {
                console.error('Error fetching packages:', err);
            }
        });
    }
    deleteItem(endpoint, id) {
        if (confirm('Are you sure you want to delete this item?')) {
            this.commonService.deleteItem(endpoint, id).subscribe({
                next: () => {
                    alert('Item deleted successfully');
                    this.fetchPackages();
                },
                error: (err) => {
                    console.error('Error deleting item:', err);
                    const errorMessage = err?.error?.message || 'Failed to delete the item';
                    alert(errorMessage);
                },
            });
        }
    }
}
