class UserListComponent {
    constructor(tableSvc, userService, commonService, route) {
        this.tableSvc = tableSvc;
        this.userService = userService;
        this.commonService = commonService;
        this.route = route;
        this.selectedSubscription = 'All';
        this.selectedStatus = 'All';
        this.displayData = [];
        this.dataList = [];
        // Pagination variables
        this.pageIndex = 1;
        this.pageSize = 10;
        this.dateRange = [];
        this.filterType = 'all';
        this.orderColumn = [
            {
                title: 'SI.No.',
            },
            {
                title: 'Joining Date',
                compare: (a, b) => a.name.localeCompare(b.name)
            },
            {
                title: 'Student Name',
                compare: (a, b) => a.name.localeCompare(b.name)
            },
            /*
            {
              title: 'Parent Name',
              compare: (a: DataItem, b: DataItem) => a.parentName.localeCompare(b.parentName)
            },
            */
            {
                title: 'Mobile Number',
                compare: (a, b) => a.mobileNumber.localeCompare(b.mobileNumber)
            },
            /*
            {
                title: 'Email',
                compare: (a: DataItem, b: DataItem) =>  a.email.localeCompare(b.email)
            },
            */
            {
                title: 'User Type',
                compare: (a, b) => a.dob.localeCompare(b.subscription)
            },
            {
                title: 'Subscription Expiry Date',
                compare: (a, b) => a.name.localeCompare(b.name)
            },
            {
                title: 'Status',
                compare: (a, b) => a.dob.localeCompare(b.status)
            },
            {
                title: 'Actions',
                compare: (a, b) => a.name.localeCompare(b.name)
            }
        ];
    }
    ngOnInit() {
        this.route.data.subscribe((data) => {
            this.filterType = data['filterType'] || 'all';
            this.fetchUsers();
        });
    }
    fetchUsers() {
        const filters = {
            fullName: this.searchInput || undefined,
            subscribed: this.selectedSubscription !== 'All' ? this.selectedSubscription : undefined,
            isActive: this.selectedStatus !== 'All' ? this.selectedStatus : undefined,
        };
        if (this.filterType === 'upcoming') {
            filters.expiresIn7Days = true;
        }
        else if (this.filterType === 'expired') {
            filters.isExpired = true;
        }
        if (this.dateRange.length === 2) {
            filters.startDate = this.dateRange[0].toISOString().split('T')[0];
            filters.endDate = this.dateRange[1].toISOString().split('T')[0];
        }
        this.displayData = [];
        this.userService.getUsers(filters, this.pageIndex, this.pageSize).subscribe({
            next: (res) => {
                this.displayData = res.result.data;
                this.dataList = res.result.data;
                this.total = res.result.totalCount;
            },
            error: (err) => {
                console.error('Error fetching users:', err);
            },
        });
    }
    search() {
        this.pageIndex = 1;
        this.fetchUsers();
    }
    subscriptionChange(value) {
        this.selectedSubscription = value;
        this.pageIndex = 1;
        this.fetchUsers();
    }
    statusChange(value) {
        this.selectedStatus = value;
        this.pageIndex = 1;
        this.fetchUsers();
    }
    onPageChange(pageIndex) {
        this.pageIndex = pageIndex;
        this.fetchUsers();
    }
    onDateRangeChange() {
        this.pageIndex = 1;
        this.fetchUsers();
    }
    exportUsers() {
        const filters = {
            fullName: this.searchInput || undefined,
            subscribed: this.selectedSubscription !== 'All' ? this.selectedSubscription : undefined,
            isActive: this.selectedStatus !== 'All' ? this.selectedStatus : undefined,
        };
        if (this.dateRange.length === 2) {
            filters.startDate = this.dateRange[0].toISOString().split('T')[0];
            filters.endDate = this.dateRange[1].toISOString().split('T')[0];
        }
        this.commonService.exportData(filters, 'student/export-students').subscribe({
            next: (response) => {
                const blob = new Blob([response], {
                    type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
                });
                const url = window.URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = 'users.xlsx';
                a.click();
                window.URL.revokeObjectURL(url);
            },
            error: (err) => {
                console.error('Error exporting users:', err);
            },
        });
    }
    isExpired(date) {
        if (!date)
            return false;
        const today = new Date();
        const endDate = new Date(date);
        return endDate < today;
    }
    deleteItem(endpoint, id) {
        if (confirm('Are you sure you want to delete this item?')) {
            this.commonService.deleteItem(endpoint, id).subscribe({
                next: () => {
                    alert('Item deleted successfully');
                    this.fetchUsers();
                },
                error: (err) => {
                    console.error('Error deleting item:', err);
                    const errorMessage = err?.error?.message || 'Failed to delete the item';
                    alert(errorMessage);
                },
            });
        }
    }
    unSubscribeStudent(endpoint, id) {
        if (confirm('Are you sure you want to Unsubscribe this student?')) {
            this.userService.unSubscribe(endpoint, id).subscribe({
                next: () => {
                    alert('Unsubscribed successfully');
                    this.fetchUsers();
                },
                error: (err) => {
                    console.error('Error:', err);
                    const errorMessage = err?.error?.message || 'Failed to Unsubscribe';
                    alert(errorMessage);
                },
            });
        }
    }
    fixedOtpStudent(endpoint, id) {
        if (confirm('Are you sure you want to make fixed OTP 112233 for this student?')) {
            this.userService.unSubscribe(endpoint, id).subscribe({
                next: () => {
                    alert('Fixed OTP 112233 added successfully');
                    this.fetchUsers();
                },
                error: (err) => {
                    console.error('Error:', err);
                    const errorMessage = err?.error?.message || 'Error';
                    alert(errorMessage);
                },
            });
        }
    }
}
